// В TypeScript нет встроенной кучи — пишем свою.
// Двоичная куча хранится в массиве: дети узла i — 2i + 1 и 2i + 2, родитель — (i - 1) >> 1.
class Heap<T> {
  private data: T[] = [];

  // less(a, b) === true, если a должен стоять ближе к вершине, чем b.
  // (a, b) => a < b — min-куча, (a, b) => a > b — max-куча
  constructor(private less: (a: T, b: T) => boolean) {}

  size(): number {
    return this.data.length;
  }

  // Вершина кучи (минимум или максимум) за O(1)
  peek(): T | undefined {
    return this.data[0];
  }

  // Добавление за O(log n): кладём в конец и «поднимаем» вверх
  push(value: T): void {
    const a = this.data;
    a.push(value);
    let i = a.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      // Родитель уже «лучше» — порядок кучи восстановлен
      if (!this.less(a[i], a[parent])) break;
      [a[i], a[parent]] = [a[parent], a[i]];
      i = parent;
    }
  }

  // Извлечение вершины за O(log n): на её место ставим последний элемент и «топим» его вниз
  pop(): T | undefined {
    const a = this.data;
    const top = a[0];
    const last = a.pop();
    if (a.length > 0 && last !== undefined) {
      a[0] = last;
      let i = 0;
      while (true) {
        const l = 2 * i + 1;
        const r = l + 1;
        // Выбираем «лучшего» из узла и двух его детей
        let best = i;
        if (l < a.length && this.less(a[l], a[best])) best = l;
        if (r < a.length && this.less(a[r], a[best])) best = r;
        if (best === i) break;
        [a[i], a[best]] = [a[best], a[i]];
        i = best;
      }
    }
    return top;
  }
}

function findMaximizedCapital(k: number, w: number, profits: number[], capital: number[]): number {
  const n = profits.length;

  // Индексы проектов по возрастанию требуемого капитала
  const order = Array.from({ length: n }, (_, i) => i).sort((a, b) => capital[a] - capital[b]);

  // Max-куча прибылей проектов, которые уже по карману
  const available = new Heap<number>((a, b) => a > b);
  let next = 0; // первый ещё не открытый проект в order

  for (let round = 0; round < k; round++) {
    // Капитал вырос — открываем все проекты, которые теперь доступны
    while (next < n && capital[order[next]] <= w) {
      available.push(profits[order[next]]);
      next++;
    }

    // Делать нечего: ни один проект не доступен
    if (available.size() === 0) break;

    // Жадно берём самый прибыльный из доступных
    w += available.pop()!;
  }

  return w;
}

// Время: O(n log n + k log n)
// Память: O(n)
